    for _, data := range poolDatas {
        for j, bitMap := range data.TickBitmaps {
            if bitMap.Cmp(big.NewInt(0)) != 0 {
                loadPopulatedTicksInWord(bitMap, wordPos, tickSpacing, tickInfo)
            }
        }
    }

    // 批量获取 liquidityNet
